// ============================================================
// ProcureGuard AI - Build Procurement Report Data
// Multi-Organization Safe Version
// ============================================================


// ------------------------------------------------------------
// 1. Get current organization data from direct input
// ------------------------------------------------------------

const input = $input.first().json;


// ------------------------------------------------------------
// 2. Current organization context
// ------------------------------------------------------------

const organizationId = input.organization_id;
const reportDate = input.report_date;
const periodStart = input.period_start;
const periodEnd = input.period_end;
const reportTimezone = input.report_timezone;


// ------------------------------------------------------------
// 3. Validate required organization/report context
// ------------------------------------------------------------

if (!organizationId) {
  throw new Error(
    "Daily report build blocked: organization_id is missing."
  );
}

if (!reportDate) {
  throw new Error(
    "Daily report build blocked: report_date is missing."
  );
}

if (!periodStart) {
  throw new Error(
    "Daily report build blocked: period_start is missing."
  );
}

if (!periodEnd) {
  throw new Error(
    "Daily report build blocked: period_end is missing."
  );
}

if (!reportTimezone) {
  throw new Error(
    "Daily report build blocked: report_timezone is missing."
  );
}


// ------------------------------------------------------------
// 4. Get arrays belonging to CURRENT organization
// ------------------------------------------------------------

const anomalies = Array.isArray(input.anomalies)
  ? input.anomalies
  : [];

const pendingApprovals =
  Array.isArray(input.pending_approvals)
    ? input.pending_approvals
    : [];

const processingErrors =
  Array.isArray(input.processing_errors)
    ? input.processing_errors
    : [];


// ------------------------------------------------------------
// 5. Safe PostgreSQL numeric conversion
// ------------------------------------------------------------

const numberValue = (value) => {
  const number = Number(value);

  return Number.isFinite(number)
    ? number
    : 0;
};


// ------------------------------------------------------------
// 6. Build metrics ONLY from current input
// No backward .item reference is used.
// ------------------------------------------------------------

const metrics = {
  invoices_received:
    numberValue(input.invoices_received),

  invoices_processed:
    numberValue(input.invoices_processed),

  invoices_review_required:
    numberValue(input.invoices_review_required),

  invoices_failed:
    numberValue(input.invoices_failed),

  anomalies_detected:
    numberValue(input.anomalies_detected),

  high_risk_anomalies:
    numberValue(input.high_risk_anomalies),

  estimated_financial_impact:
    numberValue(input.estimated_financial_impact),

  pending_approvals:
    numberValue(input.pending_approvals_count),

  open_processing_errors:
    numberValue(input.open_processing_errors),
};


// ------------------------------------------------------------
// 7. Sort anomalies defensively
// CRITICAL -> HIGH -> MEDIUM -> LOW
// Then highest estimated impact first
// ------------------------------------------------------------

const severityRank = {
  CRITICAL: 1,
  HIGH: 2,
  MEDIUM: 3,
  LOW: 4,
};


const sortedAnomalies = [...anomalies].sort(
  (a, b) => {

    const rankA =
      severityRank[a.severity] ?? 5;

    const rankB =
      severityRank[b.severity] ?? 5;


    if (rankA !== rankB) {
      return rankA - rankB;
    }


    return (
      numberValue(
        b.estimated_financial_impact
      ) -
      numberValue(
        a.estimated_financial_impact
      )
    );
  }
);


// ------------------------------------------------------------
// 8. Return exactly ONE report item for current organization
// ------------------------------------------------------------

return [
  {
    json: {

      organization_id:
        organizationId,

      report_date:
        reportDate,

      period_start:
        periodStart,

      period_end:
        periodEnd,

      report_timezone:
        reportTimezone,

      metrics,

      anomalies:
        sortedAnomalies,

      pending_approvals:
        pendingApprovals,

      processing_errors:
        processingErrors,

      generated_at:
        new Date().toISOString(),

    },
  },
];

// ============================================================
// ProcureGuard AI - Validate Daily Procurement Report
// ============================================================


// 1. Authoritative report for CURRENT loop iteration
const report =
  $("Code - Build Procurement Report Data").item.json;

if (!report || !report.organization_id) {
  throw new Error(
    "Authoritative procurement report data is missing."
  );
}


// 2. AI response comes directly into this node
const inputItems = $input.all();

if (!inputItems.length) {
  throw new Error(
    "AI executive summary returned no output."
  );
}

const ai = inputItems[0].json;


// 3. Extract AI summary
let executiveSummary = "";

if (
  Array.isArray(ai.output) &&
  ai.output.length > 0 &&
  Array.isArray(ai.output[0]?.content)
) {
  const textPart =
    ai.output[0].content.find(
      part =>
        typeof part?.text === "string" &&
        part.text.trim().length > 0
    );

  if (textPart) {
    executiveSummary = textPart.text;
  }
}


// Fallback response formats
if (
  !executiveSummary &&
  typeof ai.output_text === "string"
) {
  executiveSummary = ai.output_text;
}

if (
  !executiveSummary &&
  typeof ai.text === "string"
) {
  executiveSummary = ai.text;
}

if (
  !executiveSummary &&
  typeof ai.content === "string"
) {
  executiveSummary = ai.content;
}

if (
  !executiveSummary &&
  typeof ai.message === "string"
) {
  executiveSummary = ai.message;
}


executiveSummary =
  String(executiveSummary || "").trim();


// 4. Validate summary
if (!executiveSummary) {
  throw new Error(
    "AI executive summary text could not be extracted. Daily report blocked."
  );
}

if (executiveSummary.length < 50) {
  throw new Error(
    "AI executive summary is unexpectedly short. Daily report blocked."
  );
}


// 5. Prevent obvious internal-data leakage
const forbiddenPatterns = [
  /\b[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}\b/i,
  /workflow_execution_id/i,
  /database uuid/i,
  /system prompt/i,
];

for (const pattern of forbiddenPatterns) {
  if (pattern.test(executiveSummary)) {
    throw new Error(
      "Executive summary contains internal implementation data. Email blocked."
    );
  }
}


// 6. Validate authoritative report fields
if (!report.report_date) {
  throw new Error(
    "Report date is missing."
  );
}

if (!report.report_timezone) {
  throw new Error(
    "Report timezone is missing."
  );
}


// 7. Create subject
const emailSubject =
  `ProcureGuard Daily Procurement Report - ${report.report_date}`;


// 8. Return validated current-organization report
return [
  {
    json: {
      report_validation_status: "VALID",

      organization_id:
        report.organization_id,

      report_date:
        report.report_date,

      reporting_period: {
        start:
          report.period_start,

        end:
          report.period_end,

        timezone:
          report.report_timezone,
      },

      email_subject:
        emailSubject,

      executive_summary:
        executiveSummary,

      metrics:
        report.metrics,

      anomalies:
        report.anomalies,

      pending_approvals:
        report.pending_approvals,

      processing_errors:
        report.processing_errors,

      generated_at:
        report.generated_at,
    },
  },
];

// ============================================================
// ProcureGuard AI - Build Daily Procurement Report Email
// Multi-Organization Safe Version
// ============================================================


// ------------------------------------------------------------
// 1. Get validated report for current organization
// ------------------------------------------------------------

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `Daily report email build expected exactly 1 organization, but received ${items.length} items.`
  );
}

const data = items[0].json;

if (!data.organization_id) {
  throw new Error(
    "Validated report organization_id is missing."
  );
}


// ------------------------------------------------------------
// 2. Find configuration belonging to THIS organization
// ------------------------------------------------------------

const configItems =
  $("DB - Get Report Configuration").all();

if (!configItems.length) {
  throw new Error(
    "Organization report configuration is missing."
  );
}


const matchingConfigItem =
  configItems.find(item =>
    String(item.json.organization_id) ===
    String(data.organization_id)
  );


if (!matchingConfigItem) {
  throw new Error(
    `No report configuration was found for organization ${data.organization_id}.`
  );
}


const reportConfig =
  matchingConfigItem.json;


// ------------------------------------------------------------
// 3. Validate organization relationship
// ------------------------------------------------------------

if (
  String(data.organization_id) !==
  String(reportConfig.organization_id)
) {
  throw new Error(
    "Report organization does not match report configuration organization."
  );
}


// ------------------------------------------------------------
// 4. Validate report configuration
// ------------------------------------------------------------

if (
  reportConfig.daily_report_enabled !== true
) {
  throw new Error(
    "Daily procurement reporting is disabled for this organization."
  );
}


const reportRecipient =
  String(
    reportConfig.daily_report_recipient || ""
  ).trim();


if (!reportRecipient) {
  throw new Error(
    "Daily report recipient is not configured."
  );
}


// Basic email-format protection
const emailPattern =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/;


if (!emailPattern.test(reportRecipient)) {
  throw new Error(
    "Daily report recipient email address is invalid."
  );
}


// ------------------------------------------------------------
// 5. Validate report
// ------------------------------------------------------------

if (
  data.report_validation_status !== "VALID"
) {
  throw new Error(
    "Daily report has not passed validation. Email generation blocked."
  );
}


// ------------------------------------------------------------
// 6. Normalize report data
// ------------------------------------------------------------

const metrics =
  data.metrics || {};

const counts =
  data.summary_counts || {};

const anomalies =
  Array.isArray(data.anomalies)
    ? data.anomalies
    : [];

const approvals =
  Array.isArray(data.pending_approvals)
    ? data.pending_approvals
    : [];

const errors =
  Array.isArray(data.processing_errors)
    ? data.processing_errors
    : [];


// ------------------------------------------------------------
// 7. Helper functions
// ------------------------------------------------------------

function safe(value, fallback = "N/A") {

  if (
    value === null ||
    value === undefined ||
    value === ""
  ) {
    return fallback;
  }

  return String(value);
}


function number(value) {

  const parsed =
    Number(value);

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}


function money(value) {

  return number(value).toLocaleString(
    "en-PK",
    {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    }
  );
}


// ------------------------------------------------------------
// 8. Important anomalies
// Maximum 5
// ------------------------------------------------------------

const importantAnomalies =
  anomalies
    .filter(a =>
      ["CRITICAL", "HIGH"].includes(
        a.severity
      )
    )
    .slice(0, 5);


let anomalySection;


if (importantAnomalies.length === 0) {

  anomalySection =
    "No CRITICAL or HIGH severity anomalies were detected during the reporting period.";

} else {

  anomalySection =
    importantAnomalies
      .map((a, index) => {

        return (
          `${index + 1}. ` +
          `[${safe(a.severity)}] ` +
          `${safe(a.anomaly_type)} | ` +
          `Supplier: ${safe(a.supplier_name)} | ` +
          `Invoice: ${safe(a.invoice_number)} | ` +
          `Estimated impact: ${money(
            a.estimated_financial_impact
          )}`
        );

      })
      .join("\n");
}


// ------------------------------------------------------------
// 9. Pending approvals
// Maximum 5
// ------------------------------------------------------------

const importantApprovals =
  approvals.slice(0, 5);


let approvalSection;


if (importantApprovals.length === 0) {

  approvalSection =
    "No pending procurement approvals require attention.";

} else {

  approvalSection =
    importantApprovals
      .map((a, index) => {

        return (
          `${index + 1}. ` +
          `${safe(a.approval_type)} | ` +
          `${safe(a.severity)} | ` +
          `Supplier: ${safe(a.supplier_name)} | ` +
          `Invoice: ${safe(a.invoice_number)}`
        );

      })
      .join("\n");
}


// ------------------------------------------------------------
// 10. Open / retrying processing errors
// Maximum 5
// ------------------------------------------------------------

const unresolvedErrors =
  errors
    .filter(e =>
      ["OPEN", "RETRYING"].includes(
        e.status
      )
    )
    .slice(0, 5);


let errorSection;


if (unresolvedErrors.length === 0) {

  errorSection =
    "No unresolved processing errors require attention.";

} else {

  errorSection =
    unresolvedErrors
      .map((e, index) => {

        return (
          `${index + 1}. ` +
          `[${safe(e.severity)}] ` +
          `${safe(e.error_stage)} | ` +
          `${safe(e.error_code)} | ` +
          `Invoice: ${safe(e.invoice_number)}`
        );

      })
      .join("\n");
}


// ------------------------------------------------------------
// 11. Build deterministic email
// ------------------------------------------------------------

const emailBody = `
PROCUREGUARD AI
DAILY PROCUREMENT REPORT

Organization:
${safe(reportConfig.organization_name)}

Report Date:
${safe(data.report_date)}

Reporting Timezone:
${safe(reportConfig.timezone)}

==================================================
EXECUTIVE SUMMARY
==================================================

${safe(data.executive_summary)}

==================================================
DAILY PROCUREMENT METRICS
==================================================

Invoices Received: ${number(
  metrics.invoices_received
)}

Invoices Processed: ${number(
  metrics.invoices_processed
)}

Invoices Requiring Review: ${number(
  metrics.invoices_review_required
)}

Failed Invoices: ${number(
  metrics.invoices_failed
)}

Anomalies Detected: ${number(
  metrics.anomalies_detected
)}

High-Risk Anomalies: ${number(
  metrics.high_risk_anomalies
)}

Estimated Financial Impact:
${money(
  metrics.estimated_financial_impact
)}

==================================================
CURRENT WORK QUEUE
==================================================

Pending Approvals:
${number(
  metrics.pending_approvals
)}

Open Processing Errors:
${number(
  metrics.open_processing_errors
)}

==================================================
HIGH-PRIORITY ANOMALIES
==================================================

${anomalySection}

==================================================
PENDING APPROVALS
==================================================

${approvalSection}

==================================================
PROCESSING ISSUES
==================================================

${errorSection}

==================================================

This report was generated automatically by ProcureGuard AI.

Estimated financial impact represents value requiring review
and should not be interpreted as confirmed financial loss.
`.trim();


// ------------------------------------------------------------
// 12. Final safety checks
// ------------------------------------------------------------

if (!data.email_subject) {
  throw new Error(
    "Daily report email subject is missing."
  );
}


if (
  !emailBody ||
  emailBody.length < 100
) {
  throw new Error(
    "Generated daily report email body is invalid."
  );
}


// ------------------------------------------------------------
// 13. Return current organization's email
// ------------------------------------------------------------

return [
  {
    json: {

      ...data,

      report_settings_id:
        reportConfig.report_settings_id,

      organization_name:
        reportConfig.organization_name,

      report_timezone:
        reportConfig.timezone,

      report_hour:
        reportConfig.report_hour,

      report_recipient:
        reportRecipient,

      email_body:
        emailBody,

      email_ready:
        true,

      report_delivery_status:
        "READY_TO_SEND"
    }
  }
];
